/// <summary>
/// Class to post free text invoice shipment to customer MDF consolidation posting
/// </summary>
public class METCustomerMDFPosting_FreeTextInvoiceShipment extends METCustomerMDFPosting_FreeTextInvoice
{

}

Method.Source:
/// <summary>
/// Get the query for fetching METCustomerMDFConsolidationTable records filtered by shipment ID
/// </summary>
/// <returns>Query</returns>
Query getQuery()
{
    return new Query(querystr(METCustomerMDFConsolidationPostingQuery_FreeTextInvoiceShipment));
}

/// <summary>
/// Update METCustomerMDFConsolidationTable records to link them to the created posting record
/// </summary>
/// <param name = "_consolidationPosting">METCustomerMDFConsolidationTable</param>
/// <param name = "_postingRefRecId">RefRecId</param>
void updateCustomerMDFConsolidationTable(METCustomerMDFConsolidationTable _consolidationPosting, RefRecId _postingRefRecId)
{
    METCustomerMDFConsolidationTable consolidationTableUpdate;

    update_recordset consolidationTableUpdate
        setting PostingRefTableId = this.getPostingTableId(),
                PostingRefRecId = _postingRefRecId
        where consolidationTableUpdate.CustAccount == _consolidationPosting.CustAccount
           && consolidationTableUpdate.ShipmentId == _consolidationPosting.ShipmentId
           && consolidationTableUpdate.CustomerMDFSetupTable == _consolidationPosting.CustomerMDFSetupTable
           && consolidationTableUpdate.PostingRefRecId == 0;
}

/// <summary>
/// Get the description for CustInvoiceLine
/// </summary>
/// <param name = "_consolidationPosting">METCustomerMDFConsolidationTable</param>
/// <returns></returns>
protected TransactionTextLarge getCustInvoiceLineDesc(METCustomerMDFConsolidationTable _consolidationPosting)
{
    return strFmt("@SYS76785", super(_consolidationPosting), _consolidationPosting.ShipmentId);
}
